import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadShallabugData(){const e=readFileSync(resolve(__dirname,"../../frontend/shallabug-wetland-explorer/shallabug-data.js"),"utf-8");return new Function(e+"\nreturn { SHALLABUG_INFO, ECOLOGY_HYDROLOGY, BIRD_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Shallabug Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadShallabugData()}),describe("SHALLABUG_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.SHALLABUG_INFO.id).toBe("shallabug-wetland"),expect(e.SHALLABUG_INFO.name).toContain("Shallabug"),expect(e.SHALLABUG_INFO.ramsarYear).toBe(2022),expect(e.SHALLABUG_INFO.ramsarSiteNo).toBe(2490),expect(e.SHALLABUG_INFO.state).toBe("Jammu & Kashmir")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SHALLABUG_INFO.quickStats)).toBe(!0),expect(e.SHALLABUG_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, marsh ecology, community livelihood, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.marshEcology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.communityLivelihood).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of migratory bird species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Eurasian Wigeon and Garganey",()=>{const t=e.BIRD_SPECIES.find(e=>"eurasian-wigeon"===e.id),a=e.BIRD_SPECIES.find(e=>"garganey"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"shallabug-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../shallabug-wetland-explorer/index.html")})})});